/// Audit log of every write to the strap. PLAN.md rule 5.
/// Contract `$defs/strapWriteEvent`: the fields beyond `eventBase` (ARCHITECTURE.md 4.3).
public struct StrapWriteFields: Codable, Hashable, Sendable {
    public var command: Int
    public var name: String?
    public var payloadHex: String
    public var priorValue: String?
    public var readback: String?
    /// When Mo tapped confirm
    public var confirmedAt: Date
    public var result: String?
    /// The contract allows an explicit `null` here; one read from a file is written back as `null`.
    public var restored: Bool?
    /// Keys that arrived as an explicit JSON `null`, so a round trip keeps them (not part of the API).
    var explicitNulls: Set<String> = []

    public init(
        command: Int,
        name: String? = nil,
        payloadHex: String,
        priorValue: String? = nil,
        readback: String? = nil,
        confirmedAt: Date,
        result: String? = nil,
        restored: Bool? = nil
    ) {
        self.command = command
        self.name = name
        self.payloadHex = payloadHex
        self.priorValue = priorValue
        self.readback = readback
        self.confirmedAt = confirmedAt
        self.result = result
        self.restored = restored
    }

    enum CodingKeys: String, CodingKey {
        case command = "command"
        case name = "name"
        case payloadHex = "payload_hex"
        case priorValue = "prior_value"
        case readback = "readback"
        case confirmedAt = "confirmed_at"
        case result = "result"
        case restored = "restored"
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        var nulls = Set<String>()
        command = try c.decode(Int.self, forKey: .command)
        name = try c.decodeIfPresent(String.self, forKey: .name)
        payloadHex = try c.decode(String.self, forKey: .payloadHex)
        priorValue = try c.decodeIfPresent(String.self, forKey: .priorValue)
        readback = try c.decodeIfPresent(String.self, forKey: .readback)
        confirmedAt = try c.decode(Date.self, forKey: .confirmedAt)
        result = try c.decodeIfPresent(String.self, forKey: .result)
        restored = try c.decodeIfPresent(Bool.self, forKey: .restored)
        if restored == nil, c.contains(.restored) { nulls.insert("restored") }
        explicitNulls = nulls
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(command, forKey: .command)
        try c.encodeIfPresent(name, forKey: .name)
        try c.encode(payloadHex, forKey: .payloadHex)
        try c.encodeIfPresent(priorValue, forKey: .priorValue)
        try c.encodeIfPresent(readback, forKey: .readback)
        try c.encode(confirmedAt, forKey: .confirmedAt)
        try c.encodeIfPresent(result, forKey: .result)
        if let v = restored { try c.encode(v, forKey: .restored) } else if explicitNulls.contains("restored") { try c.encodeNil(forKey: .restored) }
    }
}

