/// One typed payload per event `type` (contract event-type-map). Encoded flat into the event object.
/// `.none` is `focus_state`, which has no typed fields in contract v0.4.
public enum EventPayload: Codable, Hashable, Sendable {
    case food(FoodFields)
    case symptom(SymptomFields)
    case checkin(CheckinFields)
    case reactionTest(ReactionTestFields)
    case nap(NapFields)
    case substance(SubstanceFields)
    case medication(MedicationFields)
    case bpCuff(BPCuffFields)
    case audio(AudioFields)
    case strapWrite(StrapWriteFields)
    case healthkit(HealthKitSampleFields)
    case workout(WorkoutFields)
    case ecg(ECGFields)
    case spo2Session(SpO2SessionFields)
    case journal(JournalFields)
    case marker(MarkerFields)
    case wear(WearFields)
    case scan(ScanFields)
    case record(RecordFields)
    case breathing(BreathingFields)
    case screenTime(ScreenTimeFields)
    case activityLabel(ActivityLabelFields)
    case none

    /// The event `type` this payload belongs to; nil for `.none` (which belongs to `focus_state`).
    public var eventType: EventType? {
        switch self {
        case .food: return .food
        case .symptom: return .symptom
        case .checkin: return .checkin
        case .reactionTest: return .reactionTest
        case .nap: return .nap
        case .substance: return .substance
        case .medication: return .medication
        case .bpCuff: return .bpCuff
        case .audio: return .audio
        case .strapWrite: return .strapWrite
        case .healthkit: return .healthkit
        case .workout: return .workout
        case .ecg: return .ecg
        case .spo2Session: return .spo2Session
        case .journal: return .journal
        case .marker: return .marker
        case .wear: return .wear
        case .scan: return .scan
        case .record: return .record
        case .breathing: return .breathingEvent
        case .screenTime: return .screenTime
        case .activityLabel: return .activityLabel
        case .none: return nil
        }
    }

    /// True when this payload is the one the contract maps `type` to.
    public func matches(_ type: EventType) -> Bool {
        if case .none = self { return type == .focusState }
        return eventType == type
    }

    /// Decodes the payload fields for `type` from the same (flat) event object.
    public static func decode(type: EventType, from decoder: Decoder) throws -> EventPayload {
        switch type {
        case .food: return .food(try FoodFields(from: decoder))
        case .symptom: return .symptom(try SymptomFields(from: decoder))
        case .checkin: return .checkin(try CheckinFields(from: decoder))
        case .reactionTest: return .reactionTest(try ReactionTestFields(from: decoder))
        case .nap: return .nap(try NapFields(from: decoder))
        case .substance: return .substance(try SubstanceFields(from: decoder))
        case .medication: return .medication(try MedicationFields(from: decoder))
        case .bpCuff: return .bpCuff(try BPCuffFields(from: decoder))
        case .audio: return .audio(try AudioFields(from: decoder))
        case .strapWrite: return .strapWrite(try StrapWriteFields(from: decoder))
        case .healthkit: return .healthkit(try HealthKitSampleFields(from: decoder))
        case .workout: return .workout(try WorkoutFields(from: decoder))
        case .ecg: return .ecg(try ECGFields(from: decoder))
        case .spo2Session: return .spo2Session(try SpO2SessionFields(from: decoder))
        case .journal: return .journal(try JournalFields(from: decoder))
        case .marker: return .marker(try MarkerFields(from: decoder))
        case .wear: return .wear(try WearFields(from: decoder))
        case .scan: return .scan(try ScanFields(from: decoder))
        case .record: return .record(try RecordFields(from: decoder))
        case .breathingEvent: return .breathing(try BreathingFields(from: decoder))
        case .screenTime: return .screenTime(try ScreenTimeFields(from: decoder))
        case .activityLabel: return .activityLabel(try ActivityLabelFields(from: decoder))
        case .focusState: return .none
        }
    }

    /// Standalone decoding reads `type` from the same object (an event object always carries it).
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: TypeKey.self)
        self = try EventPayload.decode(type: c.decode(EventType.self, forKey: .type), from: decoder)
    }

    /// Standalone encoding writes `type` (when the payload names one) plus the payload fields.
    public func encode(to encoder: Encoder) throws {
        if let t = eventType {
            var c = encoder.container(keyedBy: TypeKey.self)
            try c.encode(t, forKey: .type)
        }
        try encodeFields(to: encoder)
    }

    /// Writes only the payload's own fields into the current object (EventRecord writes eventBase itself).
    func encodeFields(to encoder: Encoder) throws {
        switch self {
        case .food(let f): try f.encode(to: encoder)
        case .symptom(let f): try f.encode(to: encoder)
        case .checkin(let f): try f.encode(to: encoder)
        case .reactionTest(let f): try f.encode(to: encoder)
        case .nap(let f): try f.encode(to: encoder)
        case .substance(let f): try f.encode(to: encoder)
        case .medication(let f): try f.encode(to: encoder)
        case .bpCuff(let f): try f.encode(to: encoder)
        case .audio(let f): try f.encode(to: encoder)
        case .strapWrite(let f): try f.encode(to: encoder)
        case .healthkit(let f): try f.encode(to: encoder)
        case .workout(let f): try f.encode(to: encoder)
        case .ecg(let f): try f.encode(to: encoder)
        case .spo2Session(let f): try f.encode(to: encoder)
        case .journal(let f): try f.encode(to: encoder)
        case .marker(let f): try f.encode(to: encoder)
        case .wear(let f): try f.encode(to: encoder)
        case .scan(let f): try f.encode(to: encoder)
        case .record(let f): try f.encode(to: encoder)
        case .breathing(let f): try f.encode(to: encoder)
        case .screenTime(let f): try f.encode(to: encoder)
        case .activityLabel(let f): try f.encode(to: encoder)
        case .none: break
        }
    }

    private enum TypeKey: String, CodingKey { case type = "type" }
}
